PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?father ?deathPlace ?deathPlaceLabel WHERE {
  <http://dbpedia.org/resource/Salin_Mibaya> dbo:parent ?father .
  ?father dbp:deathPlace ?deathPlace .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER (lang(?deathPlaceLabel) = "en") }
}
LIMIT 100

